package service;
import db.*;import java.sql.*;import java.util.*;import util.KetNoiDB;import security.PhanQuyen;
/** S6-07: đọc chuyến thật từ migration S6-06; chưa giao không phát sinh bút toán nhập trả. */
public class TheoDoiChuyenService {
 public Map<String,Object> list(long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){String scope=KhoService.manager(roles)?"":" AND EXISTS(SELECT 1 FROM user_warehouses uw WHERE uw.user_id=? AND uw.warehouse_id=t.warehouse_id)";var trips=TruyVanDB.rows(c,"SELECT t.id,t.code,t.region,t.expected_at::text expected_at,t.departed_at::text departed_at,t.expected_at<CURRENT_TIMESTAMP overdue,w.name warehouse,d.name driver,v.plate vehicle,count(s.id) total_stops,count(s.id) FILTER(WHERE dc.outcome='SUCCESS') delivered_stops,count(s.id) FILTER(WHERE dc.returned_to_warehouse) returned_stops,count(s.id) FILTER(WHERE dc.id IS NULL OR (dc.outcome<>'SUCCESS' AND NOT dc.returned_to_warehouse)) remaining_stops,count(s.id) FILTER(WHERE dc.id IS NULL) pending_stops,ROUND(COALESCE(SUM(val.amount) FILTER(WHERE dc.id IS NULL OR (dc.outcome<>'SUCCESS' AND NOT dc.returned_to_warehouse)),0),2) value_on_road FROM delivery_trips t JOIN warehouses w ON w.id=t.warehouse_id JOIN delivery_drivers d ON d.id=t.driver_id JOIN delivery_vehicles v ON v.id=t.vehicle_id JOIN delivery_trip_stops s ON s.trip_id=t.id LEFT JOIN delivery_confirmations dc ON dc.order_id=s.order_id LEFT JOIN LATERAL(SELECT SUM(COALESCE(l.delivered_base_quantity,0)/l.conversion_factor*l.line_total/l.quantity) amount FROM order_lines l WHERE l.order_id=s.order_id) val ON true WHERE t.status='IN_TRANSIT'"+scope+" GROUP BY t.id,w.name,d.name,v.plate ORDER BY t.expected_at,t.id LIMIT 500",KhoService.manager(roles)?new Object[]{}:new Object[]{user});java.math.BigDecimal total=java.math.BigDecimal.ZERO;for(var t:trips)total=total.add((java.math.BigDecimal)t.get("value_on_road"));return Map.of("items",trips,"valueOnRoad",total,"canWrite",PhanQuyen.allows(roles,"inventory.write"));}}
 public Map<String,Object> detail(long id,long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){var h=TruyVanDB.one(c,"SELECT id,code,warehouse_id,status FROM delivery_trips WHERE id=?",id);if(h==null)throw new NoSuchElementException("Không tìm thấy chuyến");KhoService.access(c,((Number)h.get("warehouse_id")).longValue(),user,roles);h.put("stops",TruyVanDB.rows(c,"SELECT s.id,s.sequence,s.order_id,o.code order_code,s.address,s.recipient_name,s.phone,dc.outcome,dc.failure_reason,COALESCE(dc.returned_to_warehouse,FALSE) returned_to_warehouse,COALESCE((SELECT SUM(l.delivered_base_quantity) FROM order_lines l WHERE l.order_id=o.id),0) shipped_quantity,ROUND(COALESCE((SELECT SUM(COALESCE(l.delivered_base_quantity,0)/l.conversion_factor*l.line_total/l.quantity) FROM order_lines l WHERE l.order_id=o.id),0),2) shipped_value FROM delivery_trip_stops s JOIN orders o ON o.id=s.order_id LEFT JOIN delivery_confirmations dc ON dc.order_id=o.id WHERE s.trip_id=? ORDER BY s.sequence",id));return h;}}
 public void complete(long id,long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){c.setAutoCommit(false);try{var h=TruyVanDB.one(c,"SELECT warehouse_id,status FROM delivery_trips WHERE id=? FOR UPDATE",id);if(h==null)throw new NoSuchElementException("Không tìm thấy chuyến");long wh=((Number)h.get("warehouse_id")).longValue();KhoService.access(c,wh,user,roles);if(!"IN_TRANSIT".equals(h.get("status")))throw new IllegalArgumentException("Chỉ kết thúc chuyến đang giao");
  if(TruyVanDB.one(c,"SELECT 1 FROM delivery_trip_stops s LEFT JOIN delivery_confirmations dc ON dc.order_id=s.order_id WHERE s.trip_id=? AND dc.id IS NULL LIMIT 1",id)!=null)throw new IllegalArgumentException("Còn điểm chưa ghi nhận kết quả giao; chuyến vẫn chịu trách nhiệm");
  KhoService.actor(c,user);TruyVanDB.one(c,"SELECT pg_advisory_xact_lock(?)",wh);
  // Hàng giao thất bại nằm trên xe tới khi chuyến về: lúc kết thúc chuyến mới nhập lại đúng lô đã xuất và huỷ đơn.
  var failed=TruyVanDB.rows(c,"SELECT dc.id,dc.order_id,dc.failure_reason,o.code FROM delivery_trip_stops s JOIN delivery_confirmations dc ON dc.order_id=s.order_id JOIN orders o ON o.id=s.order_id WHERE s.trip_id=? AND dc.outcome='FAILED' AND NOT dc.returned_to_warehouse ORDER BY s.order_id FOR UPDATE OF dc,o",id);
  var delivery=new XacNhanGiaoHangService();
  for(var f:failed){long order=((Number)f.get("order_id")).longValue();String reason=String.valueOf(f.get("failure_reason"));
   delivery.returnGoods(c,order,wh,user,String.valueOf(f.get("code")),reason);
   TruyVanDB.update(c,"UPDATE delivery_confirmations SET returned_to_warehouse=TRUE WHERE id=?",f.get("id"));
   String text="Giao thất bại, hàng đã hoàn kho khi kết thúc chuyến: "+reason;if(text.length()>500)text=text.substring(0,500);
   TrangThaiDonHang.setContext(c,user,text);
   if(TruyVanDB.update(c,"UPDATE orders SET status='CANCELLED',cancel_reason=? WHERE id=? AND status='SHIPPED'",text,order)!=1)throw new IllegalArgumentException("Trạng thái đơn "+f.get("code")+" đã thay đổi, vui lòng tải lại");}
  TruyVanDB.update(c,"UPDATE delivery_trips SET status='COMPLETED',completed_at=CURRENT_TIMESTAMP WHERE id=?",id);c.commit();}catch(SQLException e){c.rollback();throw TrangThaiDonHang.rethrow(e);}catch(RuntimeException e){c.rollback();throw e;}}}
}
